mapper.select:
SELECT DATE_FORMAT(a.schedule_date, '%Y-%m-%d') AS '排班日期', a.user_name AS '员工姓名', s.shift_name AS '班次名称', s.shift_type AS '班次类型', CONCAT(s.start_time, '-', s.end_time) AS '班次时间', CASE a.status WHEN 'SCHEDULED' THEN '已排班' WHEN 'CONFIRMED' THEN '已确认' WHEN 'CANCELLED' THEN '已取消' WHEN 'COMPLETED' THEN '已完成' ELSE a.status END AS '状态', a.work_hours AS '工作时长', DATE_FORMAT(a.check_in_time, '%H:%i:%s') AS '签到时间', DATE_FORMAT(a.check_out_time, '%H:%i:%s') AS '签退时间', a.notes AS '备注', DATE_FORMAT(a.create_time, '%Y-%m-%d %H:%i:%s') AS '创建时间' FROM jsh_schedule_assignment a LEFT JOIN jsh_schedule_shift s ON a.shift_id = s.id AND ifnull(s.delete_flag,'0') != '1' WHERE a.tenant_id = #{tenantId,jdbcType=BIGINT} AND ifnull(a.delete_flag,'0') != '1' AND a.schedule_date BETWEEN #{startDate,jdbcType=DATE} AND #{endDate,jdbcType=DATE}
AND a.user_id = #{userId,jdbcType=BIGINT}
AND a.shift_id = #{shiftId,jdbcType=BIGINT}
AND a.status = #{status,jdbcType=VARCHAR}
ORDER BY a.schedule_date ASC, s.sort_order ASC, a.user_name ASC
